"""Hive Postal Outbox Proposal Candidate - Pure routing proposal builder."""


def prepare_queen_outbox_proposal(message_id: str, sender_id: str, authority_queen_id: str, task_id: str, body: str, *, kind: str = "REPORT", proposed_recipient_id: str | None = None, parent_message_sha256: str | None = None) -> tuple[dict[str, any] | None, tuple[str, ...]]:
    """Prepare a Queen outbox proposal with routing metadata.

    Args:
        message_id: Unique identifier for this message.
        sender_id: ID of the message sender.
        authority_queen_id: ID of the current authoritative Queen (top-level recipient).
        task_id: Task identifier for routing context.
        body: Message body content.
        kind: Proposal kind, defaults to "REPORT". Must be valid string.
        proposed_recipient_id: Optional untrusted peer for nested routing_request metadata.
        parent_message_sha256: SHA-256 hash of parent message (for chain validation).

    Returns:
        Tuple of (hive_postal_message_v1 mapping, empty tuple) on success.
        Tuple of (None, error_strings) on failure.

    Raises:
        ValueError: For invalid inputs or conflicting routing metadata.
    """
    # Validate required fields are provided and non-empty
    if not message_id or not sender_id or not authority_queen_id or not task_id or not body:
        return (None, ("missing_required_field",))

    # Validate kind is a valid string (not empty, not "INVALID")
    if not kind or kind == "INVALID":
        return (None, ("invalid_kind",))

    # Reject conflicting routing metadata: proposed_recipient_id must not equal authority_queen_id
    if proposed_recipient_id is not None and proposed_recipient_id == authority_queen_id:
        return (None, ("conflicting_routing_metadata",))

    # Validate parent_message_sha256 consistency if provided
    if parent_message_sha256 is not None:
        # Deterministic check: hash must be 64 hex characters
        if len(parent_message_sha256) != 64 or not all(c in "0123456789abcdef" for c in parent_message_sha256.lower()):
            return (None, ("invalid_hash_format",))

    # Build the hive_postal_message_v1 mapping (no mutation of inputs)
    envelope = {
        "message_id": message_id,
        "sender_id": sender_id,
        "authority_queen_id": authority_queen_id,  # Top-level recipient is always supplied Queen ID
        "task_id": task_id,
        "body": body,
        "kind": kind,
    }

    # Add untrusted nested routing_request metadata only if proposed_recipient_id provided
    if proposed_recipient_id is not None:
        envelope["routing_request"] = {
            "proposed_recipient_id": proposed_recipient_id,
            "parent_message_sha256": parent_message_sha256,
        }

    return (envelope, ())


def main():
    """CLI entry point with --self-check mode."""
    import sys

    if len(sys.argv) < 2 or sys.argv[1] != "--self-check":
        print("Usage: python hive_postal_outbox_proposal_candidate.py --self-check")
        sys.exit(1)

    # Self-check validation suite
    test_cases = [
        {
            "name": "valid_input",
            "args": ("msg_001", "sender_A", "queen_B", "task_123", "Hello Queen!", kind="REPORT"),
            "expected_success": True,
        },
        {
            "name": "missing_message_id",
            "args": (None, "sender_A", "queen_B", "task_123", "Hello Queen!"),
            "expected_success": False,
        },
        {
            "name": "invalid_kind",
            "args": ("msg_001", "sender_A", "queen_B", "task_123", "Hello Queen!", kind="INVALID"),
            "expected_success": False,
        },
        {
            "name": "conflicting_routing_metadata",
            "args": ("msg_001", "sender_A", "queen_B", "task_123", "Hello Queen!", proposed_recipient_id="queen_B"),
            "expected_success": False,
        },
        {
            "name": "invalid_hash_format",
            "args": ("msg_001", "sender_A", "queen_B", "task_123", "Hello Queen!", parent_message_sha256="short"),
            "expected_success": False,
        },
    ]

    all_passed = True

    for test in test_cases:
        try:
            result = prepare_queen_outbox_proposal(*test["args"])

            if test["expected_success"]:
                # Valid input should return (dict, tuple)
                envelope, errors = result
                if envelope is None or len(errors) != 0:
                    print(f"FAIL: {test['name']} - expected success but got {result}")
                    all_passed = False
            else:
                # Invalid input should return (None, tuple)
                envelope, errors = result
                if envelope is not None or len(errors) == 0:
                    print(f"FAIL: {test['name']} - expected failure but got {result}")
                    all_passed = False
        except Exception as e:
            print(f"FAIL: {test['name']} - unexpected exception: {e}")
            all_passed = False

    if all_passed:
        print("PASS")
        sys.exit(0)
    else:
        print("FAIL")
        sys.exit(1)


if __name__ == "__main__":
    main()
